/** језгро_вриједност 안의 연결형 бајт_вриједност ток_вриједност. Ethernet/TCP 패킷 스택이 아닌 루프백 socket слој_вриједност. */
public final class ток_Мрежа {
    static int[] стање_вриједност = new int[16], порт_вриједност = new int[16], 짝 = new int[16], peer_порт = new int[16], 대기 = new int[16], 묶임 = new int[16];
    static int[] 앞 = new int[16], 수 = new int[16], подаци = new int[16 * 1024];
    static int 다음 = 50000;
    static int потврдити(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && стање_вриједност[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int 접속번호) { for (int петља_индекс = 0; петља_индекс < 16; петља_индекс++) if (стање_вриједност[петља_индекс] != 0 && 묶임[петља_индекс] != 0 && порт_вриједност[петља_индекс] == 접속번호) return true; return false; }
    public static int 만들기() {
        for (int петља_индекс = 0; петља_индекс < 16; петља_индекс++) if (стање_вриједност[петља_индекс] == 0) { стање_вриједност[петља_индекс] = 1; peer_порт[петља_индекс] = порт_вриједност[петља_индекс] = 앞[петља_индекс] = 수[петља_индекс] = 대기[петља_индекс] = 묶임[петља_индекс] = 0; 짝[петља_индекс] = -1; return петља_индекс + 40; }
        return -24;
    }
    public static int повезати_крајња_тачка_bbe6b410(int 열린파일번호, int 통신주소, int 접속번호) {
        int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (стање_вриједност[петља_индекс] != 1 || 접속번호 < 0 || 접속번호 > 65535) return -22;
        if (접속번호 == 0) { do { 접속번호 = 다음++; if (다음 > 65535) 다음 = 50000; } while (사용중(접속번호)); }
        if (사용중(접속번호)) return -98; порт_вриједност[петља_индекс] = 접속번호; 묶임[петља_индекс] = 1; стање_вриједност[петља_индекс] = 2; return 0;
    }
    public static int слушати_крајња_тачка(int 열린파일번호, int 연결대기한도) { int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9; if (стање_вриједност[петља_индекс] != 2 || 연결대기한도 < 1) return -22; стање_вриједност[петља_индекс] = 3; return 0; }
    public static int повезати(int 열린파일번호, int 통신주소, int 접속번호) {
        int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (접속번호 < 1 || 접속번호 > 65535 || стање_вриједност[петља_индекс] > 2) return -22;
        int 수신쪽 = -1; for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (стање_вриједност[안쪽자리] == 3 && порт_вриједност[안쪽자리] == 접속번호) 수신쪽 = 안쪽자리;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (대기[안쪽자리] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (стање_вриједност[петља_индекс] == 1) { int 처리값 = повезати_крајња_тачка_bbe6b410(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = 만들기(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        стање_вриједност[петља_индекс] = стање_вриједност[다른번호] = 4; 짝[петља_индекс] = 다른번호; 짝[다른번호] = петља_индекс; порт_вриједност[다른번호] = 접속번호; peer_порт[петља_индекс] = 접속번호; peer_порт[다른번호] = порт_вриједност[петља_индекс]; 대기[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int 받음(int 열린파일번호) { int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9; if (стање_вриједност[петља_индекс] != 3) return -22; for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (стање_вриједност[안쪽자리] != 0 && 대기[안쪽자리] == петља_индекс + 1) { 대기[안쪽자리] = 0; return 안쪽자리 + 40; } return -11; }
    public static int писати(int 열린파일번호, int 항목수) {
        int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9; if (стање_вриједност[петља_индекс] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int 안쪽자리 = 짝[петља_индекс]; if (안쪽자리 < 0) return -32; int 총수 = 1024 - 수[안쪽자리]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int 비교자리 = 0; 비교자리 < 총수; 비교자리++) подаци[안쪽자리 * 1024 + (앞[안쪽자리] + 수[안쪽자리] + 비교자리) % 1024] = 되돌림망.прослиједити_вриједност[비교자리]; 수[안쪽자리] += 총수; return 총수;
    }
    public static int 읽기(int 열린파일번호, int 항목수) {
        int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9; if (стање_вриједност[петља_индекс] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[петља_индекс] == 0) return 짝[петља_индекс] < 0 ? 0 : -11; if (항목수 > 수[петља_индекс]) 항목수 = 수[петља_индекс];
        for (int 비교자리 = 0; 비교자리 < 항목수; 비교자리++) 되돌림망.прослиједити_вриједност[비교자리] = подаци[петља_индекс * 1024 + (앞[петља_индекс] + 비교자리) % 1024]; 앞[петља_индекс] = (앞[петља_индекс] + 항목수) % 1024; 수[петља_индекс] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int петља_индекс = потврдити(열린파일번호); return петља_индекс < 0 ? -9 : порт_вриједност[петља_индекс]; }
    public static int 상대창구읽기(int 열린파일번호) { int петља_индекс = потврдити(열린파일번호); return петља_индекс < 0 ? -9 : peer_порт[петља_индекс]; }
    public static int затворити(int 열린파일번호) {
        int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9;
        if (стање_вриједност[петља_индекс] == 3) for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (대기[안쪽자리] == петља_индекс + 1) { if (짝[안쪽자리] >= 0) 짝[짝[안쪽자리]] = -1; стање_вриједност[안쪽자리] = 대기[안쪽자리] = 묶임[안쪽자리] = 0; }
        if (짝[петља_индекс] >= 0) 짝[짝[петља_индекс]] = -1; стање_вриједност[петља_индекс] = 묶임[петља_индекс] = 수[петља_индекс] = 대기[петља_индекс] = 0; return 0;
    }
}
